"""Embeds compiled SPIR-V modules as C++ arrays.

usage: embed_spirv.py <out.cpp> <out.h> <name>=<file.spv> ...
Each module becomes `extern const HRL_VkShaderBlob hrl_vk_<name>;`.
"""
import struct
import sys

out_cpp, out_h = sys.argv[1], sys.argv[2]
entries = [a.split("=", 1) for a in sys.argv[3:]]

header = [
    "// Generated by tools/embed_spirv.py - do not edit.",
    "#ifndef HRL_VK_SHADERS_GENERATED_H",
    "#define HRL_VK_SHADERS_GENERATED_H",
    "#include <cstddef>",
    "#include <cstdint>",
    "struct HRL_VkShaderBlob { const uint32_t* code; size_t size; /* bytes */ };",
]
source = ["// Generated by tools/embed_spirv.py - do not edit.", '#include "hrl_vk_shaders.h"']
for name, path in entries:
    with open(path, "rb") as f:
        data = f.read()
    if len(data) % 4 != 0 or len(data) < 20 or struct.unpack("<I", data[:4])[0] != 0x07230203:
        sys.exit(f"{path}: not a SPIR-V module")
    words = struct.unpack(f"<{len(data) // 4}I", data)
    header.append(f"extern const HRL_VkShaderBlob hrl_vk_{name};")
    source.append(f"static const uint32_t code_{name}[] = {{")
    for i in range(0, len(words), 12):
        source.append(",".join(f"0x{w:08x}" for w in words[i:i + 12]) + ",")
    source.append("};")
    source.append(f"const HRL_VkShaderBlob hrl_vk_{name} = {{code_{name}, sizeof(code_{name})}};")
header.append("#endif")
with open(out_h, "w") as f:
    f.write("\n".join(header) + "\n")
with open(out_cpp, "w") as f:
    f.write("\n".join(source) + "\n")
